49	/**
50	 * Retorna o modo de dispositivo atual: `mobile`, `tablet` ou `desktop`.
51	 * Reage a mudanças de viewport e orientação.
52	 */
53	export function useDeviceMode(): DeviceMode {
54	  const [mode, setMode] = React.useState<DeviceMode>(() => readDeviceMode());
55	
56	  React.useLayoutEffect(() => {
57	    let timeoutId: ReturnType<typeof setTimeout> | undefined;
58	
59	    const update = () => {
60	      setMode(readDeviceMode());
61	      // No iOS, durante rotação física, o viewport "settles" alguns frames
62	      // depois do evento. Re-checa após 250ms pra garantir sincronização.
63	      if (timeoutId) clearTimeout(timeoutId);
64	      timeoutId = setTimeout(() => setMode(readDeviceMode()), 250);
65	    };
66	
67	    update();
68	
69	    const queries = [
70	      window.matchMedia(`(max-width: ${MOBILE_BREAKPOINT - 1}px)`),
71	      window.matchMedia(
72	        `(min-width: ${MOBILE_BREAKPOINT}px) and (max-width: ${TABLET_BREAKPOINT - 1}px)`,
73	      ),
74	      window.matchMedia(`(min-width: ${TABLET_BREAKPOINT}px)`),
75	      window.matchMedia('(orientation: landscape)'),
76	      window.matchMedia('(orientation: portrait)'),
77	    ];
78	    queries.forEach((mq) => mq.addEventListener('change', update));
79	    window.addEventListener('resize', update);
80	    window.addEventListener('orientationchange', update);
81	
82	    return () => {
83	      if (timeoutId) clearTimeout(timeoutId);
84	      queries.forEach((mq) => mq.removeEventListener('change', update));
85	      window.removeEventListener('resize', update);
86	      window.removeEventListener('orientationchange', update);
87	    };
88	  }, []);
89	
90	  return mode;
91	}
