import { SidebarProvider } from '@/shared/ui/sidebar';
import { AppSidebar } from './AppSidebar';
import { StoreChangeNotification } from './StoreChangeNotification';
import { usePendingNfCaptureRedirect } from '@/features/notas-fiscais/model/usePendingNfCaptureRedirect';
import { useIsMobile } from '@/shared/hooks/use-mobile';
import { useLocation } from 'react-router-dom';
import { cn } from '@/shared/lib/utils';
import { useActivityTracker } from '@/hooks/useActivityTracker';
import { useMiaBehaviorTracker, useCounterfactualTracker } from '@/shared/lib/analytics';

interface DashboardLayoutProps {
  children: React.ReactNode;
}

/**
 * Inner — renderiza UI. Separado do Provider pra poder consumir o context.
 */
function DashboardLayoutInner({ children }: DashboardLayoutProps) {
  useActivityTracker();
  useMiaBehaviorTracker();
  useCounterfactualTracker();
  usePendingNfCaptureRedirect();
  const isMobile = useIsMobile();
  const location = useLocation();
  const isDashboard = location.pathname === '/dashboard';

  // Pages that use p-0 (full-bleed content, no padding)
  const isFullBleedPage =
    (isMobile && isDashboard) ||
    location.pathname === '/dashboard' ||
    location.pathname.startsWith('/eventos') ||
    location.pathname.startsWith('/producao') ||
    location.pathname === '/verificacao-perdas' ||
    location.pathname === '/marketing' ||
    location.pathname === '/encomendas' ||
    location.pathname === '/produtos' ||
    location.pathname === '/produtos/analytics' ||
    location.pathname === '/notas-fiscais' ||
    location.pathname === '/financeiro' ||
    location.pathname === '/movimentacoes' ||
    location.pathname === '/pronta-entrega' ||
    location.pathname === '/producao-diaria' ||
    location.pathname === '/etiquetas' ||
    location.pathname === '/mia' ||
    location.pathname === '/logistica' ||
    location.pathname === '/logistica/control-tower' ||
    location.pathname === '/requisicao' ||
    location.pathname === '/requisicao-conclusao' ||
    location.pathname === '/atendimento-virtual' ||
    location.pathname === '/noaa-supervisor' ||
    location.pathname === '/funcionarios' ||
    location.pathname.startsWith('/funcionarios/') ||
    location.pathname === '/freelancers' ||
    location.pathname.startsWith('/gestao/') ||
    location.pathname === '/tv' ||
    location.pathname.startsWith('/tv/') ||
    location.pathname.startsWith('/financeiro/cmv');

  return (
    <SidebarProvider defaultOpen={!isMobile}>
      <StoreChangeNotification />
      <div className="h-screen overflow-hidden flex w-full bg-background">
        <AppSidebar />
        <div className="flex-1 flex flex-col min-w-0 min-h-0 h-full">
          <main
            className={cn(
              'flex-1 min-h-0 overflow-y-auto overflow-x-hidden max-w-full flex flex-col',
              (!isMobile || !isDashboard) && 'pb-[env(safe-area-inset-bottom)]',
              isFullBleedPage ? 'p-0' : 'p-3 sm:p-4 md:p-6',
            )}
          >
            {children}
          </main>
        </div>
      </div>
    </SidebarProvider>
  );
}

/**
 * DashboardLayout — wrapper público. MiaProvider foi MOVIDO pro App.tsx
 * (acima de Routes) pra persistir state entre navegações — antes ele
 * re-montava em cada route change, fazendo chat sumir + tab resetar
 * quando MIA usava do_navigate.
 */
export function DashboardLayout({ children }: DashboardLayoutProps) {
  return <DashboardLayoutInner>{children}</DashboardLayoutInner>;
}

import { Lock, LogOut, User, ChevronsLeft, Moon, Sun, ChevronDown, Gauge } from "lucide-react";
import { NavLink, useLocation } from "react-router-dom";
import { useIsMobile } from "@/shared/hooks/use-mobile";
import { useAuth } from "@/shared/hooks/useAuth";
import { useTheme } from "next-themes";
import { toast } from "sonner";

import {
  Sidebar,
  SidebarContent,
  SidebarFooter,
  SidebarGroup,
  SidebarGroupContent,
  SidebarGroupLabel,
  SidebarMenu,
  SidebarMenuButton,
  SidebarMenuItem,
  SidebarTrigger,
  useSidebar,
} from "@/shared/ui/sidebar";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuLabel,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from "@/shared/ui/dropdown-menu";
import { Avatar, AvatarFallback } from "@/shared/ui/avatar";
import {
  painelItems,
  estoqueItems,
  producaoItems,
  logisticaItems,
  financeiroItems,
  gerenciaItems,
  sistemaItems,
} from "./menuItems";
import { usePermissions } from "@/shared/hooks/usePermissions";
import { cn } from "@/shared/lib/utils";
import { StoreSelector } from "@/shared/ui/DashboardStoreSelector";
import { ThemeToggle } from "@/shared/ui/ThemeToggle";
import { useMiaProactiveBadge } from "@/features/mia/model";
import { GestaoAlertasBell } from "@/features/gestao";
export function AppSidebar() {
  const { state, toggleSidebar } = useSidebar();
  const location = useLocation();
  const currentPath = location.pathname;
  const collapsed = state === "collapsed";
  const isMobile = useIsMobile();
  const { hasPermission, isAdmin } = usePermissions();
  const { signOut, user } = useAuth();
  const { theme, setTheme } = useTheme();
  const miaProactiveCount = useMiaProactiveBadge();

  const userName = user?.user_metadata?.nome || 'Usuário';
  const userInitials = userName.slice(0, 2).toUpperCase();

  const handleSignOut = async () => {
    await signOut();
    toast.success('Logout realizado com sucesso!');
  };


  const getNavCls = ({ isActive }: { isActive: boolean }) =>
    isActive
      ? "bg-primary text-primary-foreground font-medium"
      : "text-gray-900 hover:bg-accent hover:text-gray-900 dark:text-slate-200 dark:hover:text-white";

  const PERMISSION_MAP: Record<string, string | null> = {
    '/dashboard': 'view_dashboard',
    '/producao-diaria': 'view_producao_diaria',
    '/produtos': 'view_produtos',
    '/movimentacoes': 'view_movimentacoes',
    '/marketing': 'view_verificacao_perdas',
    '/verificacao-perdas': 'view_verificacao_perdas',
    '/pronta-entrega': 'view_pronta_entrega',
    '/etiquetas': 'view_visualizacao_estoque',
    '/logistica/control-tower': 'view_torre_controle',
    '/logistica': 'view_logistica',
    '/requisicao': 'view_requisicao',
    '/encomendas': 'view_encomendas',
    '/eventos': 'view_eventos',
    '/financeiro': 'view_financeiro',
    '/financeiro/cmv': 'view_financeiro',
    '/notas-fiscais': 'view_notas_fiscais',
    '/usuarios': 'admin_permissions',
    // Módulo Funcionários: gates por permissão (admin sempre passa).
    // rh_admin tem todas; gerente/rh_analista podem ter view_funcionarios.
    '/funcionarios': 'view_funcionarios',
    '/freelancers': 'view_funcionarios',
    '/funcionarios/cargos': 'manage_cargos',
    '/funcionarios/novo': 'edit_funcionarios',
    '/funcionarios/experiencia': 'decide_experiencia',
    '/funcionarios/organograma': 'view_funcionarios',
    '/funcionarios/desligamentos': 'view_funcionarios',
    '/funcionarios/ferias': 'view_funcionarios',
    '/funcionarios/ferias/calendario': 'view_funcionarios',
    '/funcionarios/metodos-punitivos': 'view_funcionarios',
    // Admin do sistema apenas:
    '/funcionarios/analytics': null,
    '/funcionarios/esocial': 'manage_esocial',
    '/funcionarios/pesquisa-clima': 'view_funcionarios_dashboard',
    // Resposta anônima é pra qualquer autenticado:
    '/pesquisa-clima': '__public__',
    '/minha-conta': '__public__',
    '/fluxogramas': 'view_fluxogramas',
    '/configuracoes': 'view_configuracoes',
    '/mia': '__public__', // MIA liberada para todos — restrições por domínio no backend
    '/atendimento-virtual': null, // admin only
    '/admin': null, // admin only
    '/tv': null, // Painel TV (Dashboard de Crise) — admin only
    '/tv/metas': null, // admin only
    // Gestão operacional N1
    '/gestao/logistica': 'view_gestao_logistica',
    '/gestao/producao': 'view_gestao_producao',
    '/gestao/estoque': 'view_gestao_estoque',
  };

  const canSeePath = (path: string): boolean => {
    if (isAdmin()) return true;

    const perm = PERMISSION_MAP[path];
    if (perm === undefined) return true;   // rota não listada = pública
    if (perm === null) return false;        // admin only (bypass já feito acima)
    if (perm === '__public__') return true;
    return hasPermission(perm);
  };

  // Todoist-style menu item renderer
  const renderMenuItems = (items: typeof painelItems) =>
    items.map((item) => {
      const allowed = canSeePath(item.url);
      return (
        <SidebarMenuItem key={item.title}>
          <SidebarMenuButton asChild className="text-sidebar-foreground rounded-md h-9 px-3">
            <NavLink
              to={item.url}
              end
              className={({ isActive }) => `${getNavCls({ isActive })} ${allowed ? '' : 'opacity-60'}`}
            >
              <div className="relative mr-2 shrink-0">
                <item.icon className="h-4 w-4" />
                {item.url === '/mia' && miaProactiveCount > 0 && (
                  <span
                    className="absolute -top-1.5 -right-1.5 h-3.5 min-w-3.5 px-0.5 rounded-full bg-red-500 text-white text-[9px] font-bold flex items-center justify-center"
                    aria-label={`${miaProactiveCount} avisos da MIA`}
                  >
                    {miaProactiveCount > 9 ? '9+' : miaProactiveCount}
                  </span>
                )}
              </div>
              {!collapsed && (
                <>
                  <span>{item.title}</span>
                  {item.subtitle && (
                    <span className="ml-2 text-[11px] text-muted-foreground/70 truncate">
                      {item.subtitle}
                    </span>
                  )}
                  {item.url === '/mia' && miaProactiveCount > 0 && (
                    <span className="ml-auto h-2 w-2 rounded-full bg-red-500" />
                  )}
                </>
              )}
              {!allowed && !collapsed && <Lock className="ml-auto h-4 w-4 opacity-60" />}
            </NavLink>
          </SidebarMenuButton>
        </SidebarMenuItem>
      );
    });

  // Painel de gestão N1: o TÍTULO do grupo vira link pro dashboard do setor —
  // só para quem tem a permission de gestão (operador comum vê label estática)
  const GESTAO_POR_GRUPO: Record<string, { path: string; perm: string; setor: string }> = {
    'Inventário': { path: '/gestao/estoque', perm: 'view_gestao_estoque', setor: 'estoque' },
    'Produção': { path: '/gestao/producao', perm: 'view_gestao_producao', setor: 'producao' },
    'Logística': { path: '/gestao/logistica', perm: 'view_gestao_logistica', setor: 'logistica' },
  };

  const renderGroupLabel = (nome: string) => {
    const gestao = GESTAO_POR_GRUPO[nome];
    const podeGerir = gestao && (isAdmin() || hasPermission(gestao.perm));
    if (!podeGerir) return <SidebarGroupLabel>{nome}</SidebarGroupLabel>;
    return (
      <SidebarGroupLabel asChild>
        <NavLink
          to={gestao.path}
          title={`Abrir painel de gestão — ${nome}`}
          data-mia-action={`abrir-gestao-${gestao.setor}`}
          className="flex w-full items-center justify-between gap-1 cursor-pointer transition-colors hover:bg-accent/50 hover:text-sidebar-foreground"
        >
          <span>{nome}</span>
          <Gauge className="h-3.5 w-3.5 opacity-70" />
        </NavLink>
      </SidebarGroupLabel>
    );
  };

  return (
    <Sidebar
      className={collapsed ? "w-14" : (isMobile ? "w-[20rem]" : "w-64")}
      collapsible="icon"
      variant={isMobile ? "floating" : "sidebar"}
    >
      <SidebarContent className="bg-card overflow-y-auto pb-0">
        {/* ─── Todoist-style top bar: User profile + collapse trigger ─── */}
        {!collapsed && (
          <div className="px-3 pt-3 pb-1 flex items-center justify-between">
            {/* User profile button (Todoist-style) */}
            <DropdownMenu>
              <DropdownMenuTrigger asChild>
                <button className="flex items-center gap-2.5 rounded-lg px-2 py-1.5 hover:bg-accent/60 transition-colors w-full text-left min-w-0">
                  <Avatar className="h-7 w-7 shrink-0">
                    <AvatarFallback className="bg-primary text-primary-foreground text-xs font-semibold">
                      {userInitials}
                    </AvatarFallback>
                  </Avatar>
                  <span className="text-sm font-semibold text-foreground truncate">
                    {userName}
                  </span>
                  <ChevronDown className="h-3.5 w-3.5 text-muted-foreground shrink-0 ml-auto" />
                </button>
              </DropdownMenuTrigger>
              <DropdownMenuContent
                className="w-64"
                align="start"
                side="bottom"
                sideOffset={4}
              >
                <DropdownMenuLabel className="font-normal">
                  <div className="flex flex-col space-y-1">
                    <p className="text-sm font-medium leading-none">
                      {userName}
                    </p>
                    <p className="text-xs leading-none text-muted-foreground">
                      {user?.email}
                    </p>
                  </div>
                </DropdownMenuLabel>
                <DropdownMenuSeparator />



                {/* Theme toggle */}
                <DropdownMenuItem
                  onClick={() => setTheme(theme === 'light' ? 'dark' : 'light')}
                >
                  {theme === 'dark' ? (
                    <Sun className="mr-2 h-4 w-4" />
                  ) : (
                    <Moon className="mr-2 h-4 w-4" />
                  )}
                  {theme === 'dark' ? 'Modo Claro' : 'Modo Escuro'}
                </DropdownMenuItem>

                <DropdownMenuItem>
                  <User className="mr-2 h-4 w-4" />
                  Perfil
                </DropdownMenuItem>

                <DropdownMenuSeparator />
                <DropdownMenuItem
                  onClick={handleSignOut}
                  className="text-destructive focus:text-destructive"
                >
                  <LogOut className="mr-2 h-4 w-4" />
                  Sair
                </DropdownMenuItem>
              </DropdownMenuContent>
            </DropdownMenu>

            {/* Collapse sidebar trigger (desktop only) */}
            {!isMobile && (
              <button
                onClick={toggleSidebar}
                className="h-7 w-7 flex items-center justify-center rounded-md hover:bg-accent/60 transition-colors text-muted-foreground hover:text-foreground shrink-0"
                title="Recolher menu (Ctrl+B)"
              >
                <ChevronsLeft className="h-4 w-4" />
              </button>
            )}
          </div>
        )}

        {/* Collapsed state: show sidebar trigger at top */}
        {collapsed && !isMobile && (
          <div className="flex justify-center pt-3 pb-1">
            <SidebarTrigger className="h-7 w-7" />
          </div>
        )}

        {/* Logo — slightly below the profile bar */}
        <div className={cn("border-b border-border", collapsed ? "p-2" : "px-4 pt-2 pb-3")}>
          <div className="flex flex-col items-center">
            {isMobile ? (
              <img
                src="/logo sistema/01. Reduzida branco.png"
                alt="Logo Momma (mobile)"
                className={cn(
                  "object-contain",
                  collapsed ? "w-8 h-8" : "w-full h-16"
                )}
              />
            ) : (
              <>
                <img
                  src="/logo sistema/01. Reduzida 5.png"
                  alt="Logo modo claro"
                  className={cn(
                    "object-contain dark:hidden",
                    collapsed ? "w-8 h-8" : "w-full h-16"
                  )}
                />
                <img
                  src="/logo sistema/01. Reduzida branco.png"
                  alt="Logo modo escuro"
                  className={cn(
                    "object-contain hidden dark:block",
                    collapsed ? "w-8 h-8" : "w-full h-16"
                  )}
                />
              </>
            )}
          </div>
        </div>

        {/* Store selector + Modo IA + theme toggle — abaixo da logo.
            Expandido: seletor ocupa o espaço + toggles à direita.
            Colapsado: empilhados verticalmente, todos compactos.
            Permissões (canChangeStore/isAdmin/canViewMia) são respeitadas dentro de cada componente. */}
        <div className={cn("border-b border-border", collapsed ? "px-2 py-2" : "px-3 py-2")}>
          <div
            className={cn(
              'flex gap-2',
              collapsed ? 'flex-col items-center' : 'flex-row items-center',
            )}
          >
            <div className={collapsed ? '' : 'flex-1 min-w-0'}>
              <StoreSelector compact={collapsed} />
            </div>
            {/* Sino de alertas de gestão — se auto-oculta sem permissão view_gestao_* */}
            <div className="shrink-0 [&_button]:h-8 [&_button]:w-8">
              <GestaoAlertasBell />
            </div>
            <div className="shrink-0 [&_button]:h-8 [&_button]:w-8">
              <ThemeToggle />
            </div>
          </div>
        </div>


        {/* ─── Navigation Groups (Todoist-style) ─── */}

        {/* Agentes IA */}
        <SidebarGroup>
          <SidebarGroupLabel>Agentes IA</SidebarGroupLabel>
          <SidebarGroupContent>
            <SidebarMenu>
              {renderMenuItems(painelItems)}
            </SidebarMenu>
          </SidebarGroupContent>
        </SidebarGroup>

        {/* Inventário — título clicável p/ gestores abre /gestao/estoque */}
        <SidebarGroup>
          {renderGroupLabel('Inventário')}
          <SidebarGroupContent>
            <SidebarMenu>
              {renderMenuItems(estoqueItems)}
            </SidebarMenu>
          </SidebarGroupContent>
        </SidebarGroup>

        {/* Produção — título clicável p/ gestores abre /gestao/producao */}
        <SidebarGroup>
          {renderGroupLabel('Produção')}
          <SidebarGroupContent>
            <SidebarMenu>
              {renderMenuItems(producaoItems)}
            </SidebarMenu>
          </SidebarGroupContent>
        </SidebarGroup>

        {/* Logística — título clicável p/ gestores abre /gestao/logistica */}
        <SidebarGroup>
          {renderGroupLabel('Logística')}
          <SidebarGroupContent>
            <SidebarMenu>
              {renderMenuItems(logisticaItems)}
            </SidebarMenu>
          </SidebarGroupContent>
        </SidebarGroup>

        {/* Financeiro */}
        <SidebarGroup>
          <SidebarGroupLabel>Financeiro</SidebarGroupLabel>
          <SidebarGroupContent>
            <SidebarMenu>
              {renderMenuItems(financeiroItems)}
            </SidebarMenu>
          </SidebarGroupContent>
        </SidebarGroup>


        {/* DP/RH */}
        <SidebarGroup>
          <SidebarGroupLabel>DP/RH</SidebarGroupLabel>
          <SidebarGroupContent>
            <SidebarMenu>
              {renderMenuItems(gerenciaItems)}
            </SidebarMenu>
          </SidebarGroupContent>
        </SidebarGroup>


        {/* Sistema */}
        <SidebarGroup>
          <SidebarGroupLabel>Sistema</SidebarGroupLabel>
          <SidebarGroupContent>
            <SidebarMenu>
              {sistemaItems.map((item) => {
                const allowed = canSeePath(item.url);
                // Admin-only: não renderizar para não-admins
                if (!allowed && PERMISSION_MAP[item.url] === null) return null;
                // "Início" (/dashboard) é a home mobile/tablet; no desktop a
                // entrada principal é a MIA, então oculta aqui.
                if (item.url === '/dashboard' && !isMobile) return null;
                return (
                  <SidebarMenuItem key={item.title}>
                    <SidebarMenuButton asChild className="text-sidebar-foreground rounded-md h-9 px-3">
                      <NavLink
                        to={item.url}
                        end
                        className={({ isActive }) => `${getNavCls({ isActive })} ${allowed ? '' : 'opacity-60'}`}
                      >
                        <item.icon className="mr-2 h-4 w-4" />
                        {!collapsed && <span>{item.title}</span>}
                        {!allowed && !collapsed && <Lock className="ml-auto h-4 w-4 opacity-60" />}
                      </NavLink>
                    </SidebarMenuButton>
                  </SidebarMenuItem>
                );
              })}
            </SidebarMenu>
          </SidebarGroupContent>
        </SidebarGroup>
      </SidebarContent>

      {/* ─── SidebarFooter: collapsed user avatar (Todoist-style) ─── */}
      {collapsed && !isMobile && (
        <SidebarFooter className="border-t border-border bg-card">
          <DropdownMenu>
            <DropdownMenuTrigger asChild>
              <button className="flex items-center justify-center w-full py-2 hover:bg-accent/60 rounded-md transition-colors">
                <Avatar className="h-7 w-7">
                  <AvatarFallback className="bg-primary text-primary-foreground text-xs font-semibold">
                    {userInitials}
                  </AvatarFallback>
                </Avatar>
              </button>
            </DropdownMenuTrigger>
            <DropdownMenuContent
              className="w-64"
              align="start"
              side="right"
              sideOffset={8}
            >
              <DropdownMenuLabel className="font-normal">
                <div className="flex flex-col space-y-1">
                  <p className="text-sm font-medium leading-none">{userName}</p>
                  <p className="text-xs leading-none text-muted-foreground">{user?.email}</p>
                </div>
              </DropdownMenuLabel>
              <DropdownMenuSeparator />
              <DropdownMenuItem
                onClick={() => setTheme(theme === 'light' ? 'dark' : 'light')}
              >
                {theme === 'dark' ? (
                  <Sun className="mr-2 h-4 w-4" />
                ) : (
                  <Moon className="mr-2 h-4 w-4" />
                )}
                {theme === 'dark' ? 'Modo Claro' : 'Modo Escuro'}
              </DropdownMenuItem>
              <DropdownMenuItem>
                <User className="mr-2 h-4 w-4" />
                Perfil
              </DropdownMenuItem>
              <DropdownMenuSeparator />
              <DropdownMenuItem
                onClick={handleSignOut}
                className="text-destructive focus:text-destructive"
              >
                <LogOut className="mr-2 h-4 w-4" />
                Sair
              </DropdownMenuItem>
            </DropdownMenuContent>
          </DropdownMenu>
        </SidebarFooter>
      )}
    </Sidebar>
  );
}

