        'after:absolute after:-inset-3 after:md:hidden md:w-5 w-8 md:h-5 h-8', // Larger touch targets on mobile
        'peer-data-[size=sm]/menu-button:top-1 md:peer-data-[size=sm]/menu-button:top-1 peer-data-[size=sm]/menu-button:top-2', // Better positioning on mobile
        'peer-data-[size=default]/menu-button:top-1.5 md:peer-data-[size=default]/menu-button:top-1.5 peer-data-[size=default]/menu-button:top-3', // Better positioning on mobile
