import { useAuth } from '@/shared/hooks/useAuth';
import { Navigate } from 'react-router-dom';
import { useEffect, useState } from 'react';
import { useDeviceMode } from '@/shared/hooks/use-mobile';

/**
 * Gerencia o redirecionamento da rota raiz (`/`).
 * Usuários autenticados e aprovados vão para `/dashboard`;
 * todos os demais são direcionados para `/auth`.
 */
export function RootRedirect() {
  const { user, loading, userProfile } = useAuth();
  const deviceMode = useDeviceMode();
  const [shouldRedirect, setShouldRedirect] = useState(false);

  useEffect(() => {
    // Aguardar um pouco para garantir que a autenticação foi verificada
    const timer = setTimeout(() => {
      setShouldRedirect(true);
    }, 100);

    return () => clearTimeout(timer);
  }, []);

  // Mostrar loading enquanto verifica autenticação
  if (loading || !shouldRedirect) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-background">
        <div className="flex flex-col items-center space-y-4">
          <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-primary"></div>
          <p className="text-muted-foreground">Carregando...</p>
        </div>
      </div>
    );
  }

  // Desktop → /mia (chat principal). Mobile/Tablet → /dashboard (hub de navegação).
  if (
    user &&
    userProfile &&
    userProfile.approved &&
    !userProfile.needs_approval
  ) {
    const target = deviceMode === 'desktop' ? '/mia' : '/dashboard';
    return <Navigate to={target} replace />;
  }

  // Se há um usuário mas precisa de aprovação, redirecionar para auth
  if (
    user &&
    userProfile &&
    (userProfile.needs_approval || !userProfile.approved)
  ) {
    return <Navigate to="/auth" replace />;
  }

  // Para todos os outros casos (usuário não autenticado, sem perfil, etc.), redirecionar para auth
  return <Navigate to="/auth" replace />;
}

