import { Navigate } from 'react-router-dom';
import { useDeviceMode } from '@/shared/hooks/use-mobile';
import MobileHome from '@/features/dashboard/ui/MobileHome';
import TabletHome from '@/features/dashboard/ui/TabletHome';
import { useMiaPageContext } from '@/features/mia/hooks/useMiaPageContext';

export default function Dashboard() {
  const deviceMode = useDeviceMode();

  useMiaPageContext({
    description: 'Dashboard principal do Momma — KPIs consolidados, vendas do dia, status das lojas, gráficos analíticos.',
    natural_language_hints: '"hoje" = vendas/produção do dia atual; "comparar lojas" = grid multi-loja; "como tá indo" = KPIs principais. Use o seletor de loja no topo pra mudar contexto.',
    capabilities: ['consultar_kpis', 'comparar_lojas', 'ver_vendas_dia', 'navegar_para_modulos'],
    primary_entity: 'dashboard_consolidado',
  });

  if (deviceMode === 'mobile') {
    return <MobileHome />;
  }

  if (deviceMode === 'tablet') {
    return <TabletHome />;
  }

  // Desktop: dashboard analítico aposentado — MIA é a entrada principal.
  return <Navigate to="/mia" replace />;
}

