14	  --mia-text-secondary:  hsl(9, 18%, 38%);         /* Derivação mais clara */
15	  --mia-text-muted:      hsl(9, 12%, 58%);         /* Muted ainda no tom */
16	  --mia-text-ai:         hsl(9, 27%, 19%);         /* Respostas da Mia — mesmo tom */
17	
18	  /* ── Acento MIA (verde esmeralda veludo — profundo, aveludado, sofisticado.
19	       Matiz 158° (esmeralda, 30° distinto do verde oliva Momma 128°),
20	       saturação 48% (rico), luminosidade 38% (profundidade veludo).
21	       Harmoniza com verde Momma e dourado. Personalidade única da Mia. ── */
22	  --mia-accent:          hsl(158, 48%, 38%);       /* Verde esmeralda veludo — primário Mia (#337D5F) */
23	  --mia-accent-hover:    hsl(158, 55%, 30%);       /* Verde veludo profundo — hover */
24	  --mia-accent-subtle:   hsl(158, 40%, 96%);       /* Verde claríssimo — backgrounds */
25	  --mia-accent-glow:     hsla(158, 60%, 38%, 0.22);/* Glow esmeralda — focus rings */
26	
27	  /* ── Thinking/Reasoning R1 (âmbar dourado — contraste narrativo com o verde
28	       veludo da Mia. Quando ela fala = verde, quando ela pensa = âmbar.
29	       Dá clareza visual sobre o estado dela sem confundir. ── */
30	  --mia-thinking-from:   hsl(42, 72%, 56%);        /* Âmbar dourado vivo (#DBA63B) */
31	  --mia-thinking-to:     hsl(32, 68%, 50%);        /* Âmbar mais quente */
32	  --mia-thinking-bg:     hsl(42, 55%, 97%);        /* Background âmbar claríssimo */
33	  --mia-thinking-border: hsl(42, 45%, 86%);        /* Borda âmbar sutil */
34	
35	  /* ── Verde Momma (sucesso, ações executadas) ── */
36	  --mia-success:         hsl(133, 17%, 33%);       /* Verde escuro Momma */
37	  --mia-success-subtle:  hsl(133, 15%, 94%);       /* Verde muito claro */
38	
39	  /* ── Glassmorphism ── */
40	  --mia-glass-bg:        hsla(46, 63%, 97%, 0.7);  /* Fundo vidro */
41	  --mia-glass-border:    hsla(35, 33%, 55%, 0.15); /* Borda vidro */
42	  --mia-glass-blur:      12px;                      /* Blur amount */
43	}
44	
45	.dark {
46	  --mia-bg:            hsl(158, 10%, 10%);
47	  --mia-bg-subtle:     hsl(158, 10%, 8%);
48	  --mia-bg-elevated:   hsl(158, 10%, 14%);
49	  --mia-bg-overlay:    hsla(158, 10%, 10%, 0.9);
50	  --mia-text-primary:  hsl(15, 20%, 93%);          /* Cream levemente quente (dark) */
51	  --mia-text-secondary:hsl(15, 14%, 72%);
52	  --mia-text-muted:    hsl(15, 10%, 55%);
53	  --mia-text-ai:       hsl(15, 20%, 92%);
54	  --mia-accent:        hsl(158, 55%, 55%);         /* Verde veludo luminoso no dark */
55	  --mia-accent-hover:  hsl(158, 60%, 48%);
56	  --mia-accent-subtle: hsl(158, 30%, 18%);
57	  --mia-accent-glow:   hsla(158, 65%, 55%, 0.28);
58	  --mia-thinking-from: hsl(42, 78%, 62%);
59	  --mia-thinking-to:   hsl(32, 72%, 58%);
60	  --mia-thinking-bg:   hsl(42, 15%, 14%);
61	  --mia-thinking-border: hsl(42, 25%, 25%);
62	  --mia-glass-bg:      hsla(158, 10%, 12%, 0.8);
63	}
64	
65	/* ── Typography ── */
66	.font-ai {
67	  font-family: 'Georgia', 'Cambria', serif;
68	}
69	
70	/* ── Momma Surface: redefine variáveis locais para integrar com design system Momma ──
71	   Aplicado nos wrappers MiaInlineChat (desktop) e MiaMobileSheet (mobile) para
72	   eliminar o tom bege padrão e deixar o wrapper pai controlar o background
73	   (branco Momma + toldo + ambient glows + glassmorphism). */
74	.mia-momma-surface {
75	  --mia-bg: transparent;
76	  --mia-bg-subtle: hsla(0, 0%, 100%, 0.5);
77	  --mia-bg-elevated: hsla(0, 0%, 100%, 0.92);
78	  --mia-bg-overlay: hsla(0, 0%, 100%, 0.85);
79	}
80	
81	/* ── MIA Activity Glow: border pulsante page-wide quando MIA está atuando ── */
82	@keyframes mia-glow-pulse {
83	  0%, 100% {
84	    box-shadow:
85	      inset 0 0 40px 0 var(--mia-accent-glow),
86	      0 0 20px 0 var(--mia-accent-glow);
87	    opacity: 0.85;
88	  }
89	  50% {
90	    box-shadow:
91	      inset 0 0 80px 0 var(--mia-accent-glow),
92	      0 0 40px 0 var(--mia-accent-glow);
93	    opacity: 1;
94	  }
95	}
96	.animate-mia-glow-pulse {
97	  animation: mia-glow-pulse 2.5s ease-in-out infinite;
98	}
99	
100	/* Bg gradient radial helper (Tailwind não tem nativo) */
101	.bg-gradient-radial {
102	  background-image: radial-gradient(circle at center, var(--tw-gradient-from), var(--tw-gradient-to));
103	}
104	
105	/* ── MIA Click Flash: feedback visual no elemento durante o click ── */
106	@keyframes mia-click-flash {
107	  0% {
108	    transform: scale(1);
109	    box-shadow: 0 0 0 0 var(--mia-accent-glow), 0 0 0 0 transparent;
110	  }
111	  30% {
112	    transform: scale(0.95);
113	    box-shadow: 0 0 0 8px var(--mia-accent-glow), 0 0 30px 0 var(--mia-accent-glow);
114	  }
115	  100% {
116	    transform: scale(1);
117	    box-shadow: 0 0 0 0 transparent, 0 0 0 0 transparent;
118	  }
119	}
120	.mia-click-flash {
121	  animation: mia-click-flash 0.4s ease-out;
122	  position: relative;
123	  z-index: 1;
124	}
125	
126	/* MIA Cursor Ripple — anel radiando do cursor no momento do click.
127	   Padrão Claude Chrome: ripple expandindo + fading. */
128	@keyframes mia-cursor-ripple {
129	  0% {
130	    transform: scale(1);
131	    opacity: 0.9;
132	    border-width: 2px;
133	  }
134	  100% {
135	    transform: scale(2.5);
136	    opacity: 0;
137	    border-width: 1px;
138	  }
139	}
140	.animate-mia-cursor-ripple {
141	  animation: mia-cursor-ripple 0.6s ease-out forwards;
142	}
143	
144	/* Sutil "respiração" do mouse pointer enquanto MIA está ativa — sinaliza vida sem atrapalhar leitura */
145	@keyframes mia-cursor-bob {
146	  0%, 100% { transform: translateY(0) rotate(0deg); }
147	  50% { transform: translateY(-1.5px) rotate(-2deg); }
148	}
149	.animate-mia-cursor-bob {
150	  animation: mia-cursor-bob 1.8s ease-in-out infinite;
151	}
152	
153	/* MIA Activity Border Glow — pulsa opacity (GPU-friendly, sem repaint).
154	   Estilo Claude for Chrome: border verde Momma ao redor da viewport quando
155	   o agent atua. Não usar animação direto em box-shadow (CPU-pesado). */
156	@keyframes mia-border-pulse {
157	  0%, 100% { opacity: 0.85; }
158	  50% { opacity: 1; }
159	}
160	.animate-mia-border-pulse {
161	  animation: mia-border-pulse 2s ease-in-out infinite;
162	  will-change: opacity;
163	}
164	
165	@keyframes mia-border-pulse-soft {
166	  0%, 100% { opacity: 0.3; }
167	  50% { opacity: 0.6; }
168	}
169	.animate-mia-border-pulse-soft {
170	  animation: mia-border-pulse-soft 3s ease-in-out infinite;
171	  will-change: opacity;
172	}
173	
174	/* ════════════════════════════════════════════════════════════════
175	   Modais respeitam MIA pane (não ficam atrás do chat à direita)
176	   ════════════════════════════════════════════════════════════════
177	   Quando html tem data-mia-pane-open="true", Dialog/Sheet do shadcn
178	   centralizam na ÁREA ERP (esquerda) ao invés do viewport inteiro.
179	   Não afeta elementos dentro do próprio MIA pane (.mia-momma-surface).
180	*/
181	html[data-mia-pane-open="true"] [role="dialog"]:not(.mia-momma-surface *):not([data-mia-skip-offset]) {
182	  /* Centraliza modal NA ÁREA ERP (esquerda) — não no viewport inteiro.
183	     Tailwind `left-[50%]` setava 50vw. Override pra (100vw - pane)/2.
184	     Transform translate(-50%, -50%) mantido pelo Tailwind. */
185	  left: calc((100vw - var(--mia-pane-width, 0px)) / 2) !important;
186	  /* Restringe largura máxima pra não invadir área do pane */
187	  max-width: calc(100vw - var(--mia-pane-width, 0px) - 48px) !important;
188	}
189	
190	/* Overlay/backdrop dos dialogs respeita ERP. Recolhe (right: pane-width)
191	   E libera pointer-events na faixa direita coberta pelo MIA pane.
192	   Sem isso, mesmo com `inset` reduzido, browsers podem manter área de
193	   captura conforme renderização. Defensive: também clip-path. */
194	html[data-mia-pane-open="true"] [data-mia-overlay="true"]:not(.mia-momma-surface *) {
195	  right: var(--mia-pane-width, 0px) !important;
196	  /* Clip extra defensivo: garantia que pixel-area não vaza pra área MIA */
197	  clip-path: inset(0 var(--mia-pane-width, 0px) 0 0) !important;
198	}
199	
200	/* Fallback pra overlays sem marker custom (libs terceiras): também recolhe */
201	html[data-mia-pane-open="true"] [role="dialog"] > [data-state="open"]:first-child:not([data-mia-overlay]) {
202	  right: var(--mia-pane-width, 0px) !important;
203	  clip-path: inset(0 var(--mia-pane-width, 0px) 0 0) !important;
204	}
205	
206	/* mia-momma-surface — wrapper do chat inline.
207	   z-index e isolation removidos: eram necessários só para o glass-box pane
208	   (split-view) que está pausado. Com eles ativos, o contexto de empilhamento
209	   ficava em z=9999, cobrindo os Portais do Radix (Popover/Dialog) que usam z=50. */
210	.mia-momma-surface {
211	  pointer-events: auto !important;
212	}
213	
214	.mia-momma-surface * {
215	  pointer-events: auto !important;
216	}
217	
218	/* Sheet (side bottom/right) — quando aberto pela direita, recuar pra dentro
219	   da área ERP. Side="right" só cobre área até o MIA pane. */
220	html[data-mia-pane-open="true"] [role="dialog"][data-state][data-side="right"]:not(.mia-momma-surface *) {
221	  right: var(--mia-pane-width, 0px) !important;
222	}
223	
224	.dark .mia-momma-surface {
225	  --mia-bg: transparent;
226	  --mia-bg-subtle: hsla(0, 0%, 0%, 0.3);
227	  --mia-bg-elevated: hsla(0, 0%, 100%, 0.08);
228	  --mia-bg-overlay: hsla(30, 10%, 4%, 0.85);
229	}
230	
231	/* ── Glassmorphism Classes ── */
232	.mia-glass {
233	  background: var(--mia-glass-bg);
234	  backdrop-filter: blur(var(--mia-glass-blur));
235	  -webkit-backdrop-filter: blur(var(--mia-glass-blur));
236	  border: 1px solid var(--mia-glass-border);
237	}
238	
239	.mia-glass-elevated {
240	  background: var(--mia-glass-bg);
241	  backdrop-filter: blur(16px);
242	  -webkit-backdrop-filter: blur(16px);
243	  border: 1px solid var(--mia-glass-border);
244	  box-shadow:
245	    0 4px 30px rgba(0, 0, 0, 0.03),
246	    0 1px 3px rgba(0, 0, 0, 0.05);
247	}
248	
249	.mia-glass-subtle {
250	  background: hsla(46, 63%, 97%, 0.4);
251	  backdrop-filter: blur(8px);
252	}
253	
254	/* ── Prose Customization ── */
255	/* Tipografia sofisticada — mesmo padrão do MiaGreetingCard headline:
256	   font-serif (Georgia), font-medium (500), tom marrom Momma #3E2723,
257	   leading snug e tracking levemente apertado para um ar editorial. */
258	.prose-mia {
259	  --tw-prose-body: var(--mia-text-ai);
260	  --tw-prose-headings: var(--mia-text-primary);
261	  --tw-prose-bold: var(--mia-text-primary);
262	  --tw-prose-links: var(--mia-accent);
263	  --tw-prose-code: var(--mia-accent-hover);
264	  font-family: 'Georgia', 'Cambria', 'Times New Roman', serif;
265	  font-size: 16px;
266	  font-weight: 450;
267	  line-height: 1.7;
268	  letter-spacing: -0.01em;
269	  color: var(--mia-text-ai);
270	}
271	
272	.prose-mia p {
273	  font-weight: 450;
274	  color: var(--mia-text-ai);
275	}
276	
277	.prose-mia strong,
278	.prose-mia h1,
279	.prose-mia h2,
280	.prose-mia h3,
281	.prose-mia h4 {
282	  font-weight: 600;
283	  color: var(--mia-text-primary);
284	  letter-spacing: -0.015em;
285	}
286	
287	.prose-mia code {
288	  font-family: 'JetBrains Mono', 'Fira Code', monospace;
289	  font-size: 13px;
290	  background: hsl(35, 20%, 95%);
291	  padding: 2px 6px;
292	  border-radius: 6px;
293	  font-weight: 400;
294	}
295	
296	.prose-mia pre {
297	  background: hsl(60, 5%, 12%);
298	  border: 1px solid hsl(60, 5%, 20%);
299	  border-radius: 12px;
300	  padding: 16px 20px;
301	  overflow-x: auto;
302	}
303	
304	.prose-mia pre code {
305	  background: transparent;
306	  padding: 0;
307	  color: hsl(46, 40%, 90%);
308	}
309	
310	.prose-mia blockquote {
311	  border-left: 3px solid var(--mia-accent);
312	  background: var(--mia-accent-subtle);
313	  padding: 12px 16px;
314	  border-radius: 0 8px 8px 0;
315	  font-style: italic;
316	}
317	
318	.prose-mia table {
319	  border: 1px solid var(--mia-glass-border);
320	  border-radius: 8px;
321	  overflow: hidden;
322	}
323	
324	.prose-mia th {
325	  background: var(--mia-accent-subtle);
326	  font-family: 'Poppins', sans-serif;
327	  font-weight: 600;
328	  font-size: 13px;
329	  text-transform: uppercase;
330	  letter-spacing: 0.05em;
331	}
332	
333	/* ── Animations ── */
334	
335	@property --thinking-angle {
336	  syntax: '<angle>';
337	  initial-value: 0deg;
338	  inherits: false;
339	}
340	
341	/* Rotating gradient border for thinking blocks */
342	@keyframes mia-thinking-rotate {
343	  to { --thinking-angle: 360deg; }
344	}
345	
346	/* Text shimmer during thinking */
347	@keyframes mia-shimmer {
348	  0% { background-position: -200% 0; }
349	  100% { background-position: 200% 0; }
350	}
351	
352	/* Cursor blink */
353	@keyframes mia-cursor-blink {
354	  0%, 100% { opacity: 1; }
355	  50% { opacity: 0; }
356	}
357	
358	/* Subtle float for welcome avatar */
359	@keyframes mia-float {
360	  0%, 100% { transform: translateY(0); }
361	  50% { transform: translateY(-6px); }
362	}
363	
364	/* Glow pulse for avatar */
365	@keyframes mia-glow-pulse {
366	  0%, 100% { opacity: 0.15; transform: scale(1); }
367	  50% { opacity: 0.3; transform: scale(1.05); }
368	}
369	
370	.mia-thinking-block {
371	  position: relative;
372	  border-radius: 16px;
373	  padding: 1px; /* Border width via padding trick */
374	  background: conic-gradient(
375	    from var(--thinking-angle),
376	    var(--mia-thinking-from),
377	    var(--mia-thinking-to),
378	    transparent 40%,
379	    var(--mia-thinking-from)
380	  );
381	  animation: mia-thinking-rotate 3s linear infinite;
382	}
383	
384	.mia-thinking-block.completed {
385	  background: var(--mia-thinking-border);
386	  animation: none;
387	}
388	
389	.mia-thinking-block__inner {
390	  background: var(--mia-thinking-bg);
391	  border-radius: 15px; /* 16px - 1px border */
392	  padding: 12px 16px;
393	}
394	
395	/* Shimmer no texto enquanto pensa */
396	.mia-thinking-text.streaming {
397	  background: linear-gradient(
398	    90deg,
399	    var(--mia-text-secondary) 0%,
400	    var(--mia-accent) 50%,
401	    var(--mia-text-secondary) 100%
402	  );
403	  background-size: 200% 100%;
404	  -webkit-background-clip: text;
405	  -webkit-text-fill-color: transparent;
406	  animation: mia-shimmer 2s ease-in-out infinite;
407	}
408	
409	@media (prefers-reduced-motion: reduce) {
410	  .mia-thinking-block { animation: none; }
411	  .mia-thinking-text.streaming { animation: none; -webkit-text-fill-color: var(--mia-text-secondary); }
412	  * { animation-duration: 0.01ms !important; transition-duration: 0.01ms !important; }
413	}
