/* ── MIA Chat Page: Design System & Animations ── */

:root {
  /* ── Superfícies ── */
  --mia-bg:              hsl(46, 63%, 97%);        /* Bege muito claro — fundo principal */
  --mia-bg-subtle:       hsl(46, 50%, 95%);        /* Bege sutil — sidebar */
  --mia-bg-elevated:     hsl(0, 0%, 100%);         /* Branco — cards, input, mensagens user */
  --mia-bg-overlay:      hsla(46, 63%, 97%, 0.85); /* Bege translúcido — input gradient fade */

  /* ── Texto (#3E2723 — quase-preto levemente quente com matiz laranja sutil.
       Mesma cor do headline do MiaGreetingCard no mobile. Não é preto absoluto,
       é um tom cálido e sofisticado — assinatura visual da Mia. ── */
  --mia-text-primary:    hsl(9, 27%, 19%);         /* #3E2723 — quase-preto quente */
  --mia-text-secondary:  hsl(9, 18%, 38%);         /* Derivação mais clara */
  --mia-text-muted:      hsl(9, 12%, 58%);         /* Muted ainda no tom */
  --mia-text-ai:         hsl(9, 27%, 19%);         /* Respostas da Mia — mesmo tom */

  /* ── Acento MIA (verde esmeralda veludo — profundo, aveludado, sofisticado.
       Matiz 158° (esmeralda, 30° distinto do verde oliva Momma 128°),
       saturação 48% (rico), luminosidade 38% (profundidade veludo).
       Harmoniza com verde Momma e dourado. Personalidade única da Mia. ── */
  --mia-accent:          hsl(158, 48%, 38%);       /* Verde esmeralda veludo — primário Mia (#337D5F) */
  --mia-accent-hover:    hsl(158, 55%, 30%);       /* Verde veludo profundo — hover */
  --mia-accent-subtle:   hsl(158, 40%, 96%);       /* Verde claríssimo — backgrounds */
  --mia-accent-glow:     hsla(158, 60%, 38%, 0.22);/* Glow esmeralda — focus rings */

  /* ── Thinking/Reasoning R1 (âmbar dourado — contraste narrativo com o verde
       veludo da Mia. Quando ela fala = verde, quando ela pensa = âmbar.
       Dá clareza visual sobre o estado dela sem confundir. ── */
  --mia-thinking-from:   hsl(42, 72%, 56%);        /* Âmbar dourado vivo (#DBA63B) */
  --mia-thinking-to:     hsl(32, 68%, 50%);        /* Âmbar mais quente */
  --mia-thinking-bg:     hsl(42, 55%, 97%);        /* Background âmbar claríssimo */
  --mia-thinking-border: hsl(42, 45%, 86%);        /* Borda âmbar sutil */

  /* ── Verde Momma (sucesso, ações executadas) ── */
  --mia-success:         hsl(133, 17%, 33%);       /* Verde escuro Momma */
  --mia-success-subtle:  hsl(133, 15%, 94%);       /* Verde muito claro */

  /* ── Glassmorphism ── */
  --mia-glass-bg:        hsla(46, 63%, 97%, 0.7);  /* Fundo vidro */
  --mia-glass-border:    hsla(35, 33%, 55%, 0.15); /* Borda vidro */
  --mia-glass-blur:      12px;                      /* Blur amount */
}

.dark {
  --mia-bg:            hsl(158, 10%, 10%);
  --mia-bg-subtle:     hsl(158, 10%, 8%);
  --mia-bg-elevated:   hsl(158, 10%, 14%);
  --mia-bg-overlay:    hsla(158, 10%, 10%, 0.9);
  --mia-text-primary:  hsl(15, 20%, 93%);          /* Cream levemente quente (dark) */
  --mia-text-secondary:hsl(15, 14%, 72%);
  --mia-text-muted:    hsl(15, 10%, 55%);
  --mia-text-ai:       hsl(15, 20%, 92%);
  --mia-accent:        hsl(158, 55%, 55%);         /* Verde veludo luminoso no dark */
  --mia-accent-hover:  hsl(158, 60%, 48%);
  --mia-accent-subtle: hsl(158, 30%, 18%);
  --mia-accent-glow:   hsla(158, 65%, 55%, 0.28);
  --mia-thinking-from: hsl(42, 78%, 62%);
  --mia-thinking-to:   hsl(32, 72%, 58%);
  --mia-thinking-bg:   hsl(42, 15%, 14%);
  --mia-thinking-border: hsl(42, 25%, 25%);
  --mia-glass-bg:      hsla(158, 10%, 12%, 0.8);
}

/* ── Typography ── */
.font-ai {
  font-family: 'Georgia', 'Cambria', serif;
}

/* ── Momma Surface: redefine variáveis locais para integrar com design system Momma ──
   Aplicado nos wrappers MiaInlineChat (desktop) e MiaMobileSheet (mobile) para
   eliminar o tom bege padrão e deixar o wrapper pai controlar o background
   (branco Momma + toldo + ambient glows + glassmorphism). */
.mia-momma-surface {
  --mia-bg: transparent;
  --mia-bg-subtle: hsla(0, 0%, 100%, 0.5);
  --mia-bg-elevated: hsla(0, 0%, 100%, 0.92);
  --mia-bg-overlay: hsla(0, 0%, 100%, 0.85);
}

/* ── MIA Activity Glow: border pulsante page-wide quando MIA está atuando ── */
@keyframes mia-glow-pulse {
  0%, 100% {
    box-shadow:
      inset 0 0 40px 0 var(--mia-accent-glow),
      0 0 20px 0 var(--mia-accent-glow);
    opacity: 0.85;
  }
  50% {
    box-shadow:
      inset 0 0 80px 0 var(--mia-accent-glow),
      0 0 40px 0 var(--mia-accent-glow);
    opacity: 1;
  }
}
.animate-mia-glow-pulse {
  animation: mia-glow-pulse 2.5s ease-in-out infinite;
}

/* Bg gradient radial helper (Tailwind não tem nativo) */
.bg-gradient-radial {
  background-image: radial-gradient(circle at center, var(--tw-gradient-from), var(--tw-gradient-to));
}

/* ── MIA Click Flash: feedback visual no elemento durante o click ── */
@keyframes mia-click-flash {
  0% {
    transform: scale(1);
    box-shadow: 0 0 0 0 var(--mia-accent-glow), 0 0 0 0 transparent;
  }
  30% {
    transform: scale(0.95);
    box-shadow: 0 0 0 8px var(--mia-accent-glow), 0 0 30px 0 var(--mia-accent-glow);
  }
  100% {
    transform: scale(1);
    box-shadow: 0 0 0 0 transparent, 0 0 0 0 transparent;
  }
}
.mia-click-flash {
  animation: mia-click-flash 0.4s ease-out;
  position: relative;
  z-index: 1;
}

/* MIA Cursor Ripple — anel radiando do cursor no momento do click.
   Padrão Claude Chrome: ripple expandindo + fading. */
@keyframes mia-cursor-ripple {
  0% {
    transform: scale(1);
    opacity: 0.9;
    border-width: 2px;
  }
  100% {
    transform: scale(2.5);
    opacity: 0;
    border-width: 1px;
  }
}
.animate-mia-cursor-ripple {
  animation: mia-cursor-ripple 0.6s ease-out forwards;
}

/* Sutil "respiração" do mouse pointer enquanto MIA está ativa — sinaliza vida sem atrapalhar leitura */
@keyframes mia-cursor-bob {
  0%, 100% { transform: translateY(0) rotate(0deg); }
  50% { transform: translateY(-1.5px) rotate(-2deg); }
}
.animate-mia-cursor-bob {
  animation: mia-cursor-bob 1.8s ease-in-out infinite;
}

/* MIA Activity Border Glow — pulsa opacity (GPU-friendly, sem repaint).
   Estilo Claude for Chrome: border verde Momma ao redor da viewport quando
   o agent atua. Não usar animação direto em box-shadow (CPU-pesado). */
@keyframes mia-border-pulse {
  0%, 100% { opacity: 0.85; }
  50% { opacity: 1; }
}
.animate-mia-border-pulse {
  animation: mia-border-pulse 2s ease-in-out infinite;
  will-change: opacity;
}

@keyframes mia-border-pulse-soft {
  0%, 100% { opacity: 0.3; }
  50% { opacity: 0.6; }
}
.animate-mia-border-pulse-soft {
  animation: mia-border-pulse-soft 3s ease-in-out infinite;
  will-change: opacity;
}

/* ════════════════════════════════════════════════════════════════
   Modais respeitam MIA pane (não ficam atrás do chat à direita)
   ════════════════════════════════════════════════════════════════
   Quando html tem data-mia-pane-open="true", Dialog/Sheet do shadcn
   centralizam na ÁREA ERP (esquerda) ao invés do viewport inteiro.
   Não afeta elementos dentro do próprio MIA pane (.mia-momma-surface).
*/
html[data-mia-pane-open="true"] [role="dialog"]:not(.mia-momma-surface *):not([data-mia-skip-offset]) {
  /* Centraliza modal NA ÁREA ERP (esquerda) — não no viewport inteiro.
     Tailwind `left-[50%]` setava 50vw. Override pra (100vw - pane)/2.
     Transform translate(-50%, -50%) mantido pelo Tailwind. */
  left: calc((100vw - var(--mia-pane-width, 0px)) / 2) !important;
  /* Restringe largura máxima pra não invadir área do pane */
  max-width: calc(100vw - var(--mia-pane-width, 0px) - 48px) !important;
}

/* Overlay/backdrop dos dialogs respeita ERP. Recolhe (right: pane-width)
   E libera pointer-events na faixa direita coberta pelo MIA pane.
   Sem isso, mesmo com `inset` reduzido, browsers podem manter área de
   captura conforme renderização. Defensive: também clip-path. */
html[data-mia-pane-open="true"] [data-mia-overlay="true"]:not(.mia-momma-surface *) {
  right: var(--mia-pane-width, 0px) !important;
  /* Clip extra defensivo: garantia que pixel-area não vaza pra área MIA */
  clip-path: inset(0 var(--mia-pane-width, 0px) 0 0) !important;
}

/* Fallback pra overlays sem marker custom (libs terceiras): também recolhe */
html[data-mia-pane-open="true"] [role="dialog"] > [data-state="open"]:first-child:not([data-mia-overlay]) {
  right: var(--mia-pane-width, 0px) !important;
  clip-path: inset(0 var(--mia-pane-width, 0px) 0 0) !important;
}

/* mia-momma-surface — wrapper do chat inline.
   z-index e isolation removidos: eram necessários só para o glass-box pane
   (split-view) que está pausado. Com eles ativos, o contexto de empilhamento
   ficava em z=9999, cobrindo os Portais do Radix (Popover/Dialog) que usam z=50. */
.mia-momma-surface {
  pointer-events: auto !important;
}

.mia-momma-surface * {
  pointer-events: auto !important;
}

/* Sheet (side bottom/right) — quando aberto pela direita, recuar pra dentro
   da área ERP. Side="right" só cobre área até o MIA pane. */
html[data-mia-pane-open="true"] [role="dialog"][data-state][data-side="right"]:not(.mia-momma-surface *) {
  right: var(--mia-pane-width, 0px) !important;
}

.dark .mia-momma-surface {
  --mia-bg: transparent;
  --mia-bg-subtle: hsla(0, 0%, 0%, 0.3);
  --mia-bg-elevated: hsla(0, 0%, 100%, 0.08);
  --mia-bg-overlay: hsla(30, 10%, 4%, 0.85);
}

/* ── Glassmorphism Classes ── */
.mia-glass {
  background: var(--mia-glass-bg);
  backdrop-filter: blur(var(--mia-glass-blur));
  -webkit-backdrop-filter: blur(var(--mia-glass-blur));
  border: 1px solid var(--mia-glass-border);
}

.mia-glass-elevated {
  background: var(--mia-glass-bg);
  backdrop-filter: blur(16px);
  -webkit-backdrop-filter: blur(16px);
  border: 1px solid var(--mia-glass-border);
  box-shadow:
    0 4px 30px rgba(0, 0, 0, 0.03),
    0 1px 3px rgba(0, 0, 0, 0.05);
}

.mia-glass-subtle {
  background: hsla(46, 63%, 97%, 0.4);
  backdrop-filter: blur(8px);
}

/* ── Prose Customization ── */
/* Tipografia sofisticada — mesmo padrão do MiaGreetingCard headline:
   font-serif (Georgia), font-medium (500), tom marrom Momma #3E2723,
   leading snug e tracking levemente apertado para um ar editorial. */
.prose-mia {
  --tw-prose-body: var(--mia-text-ai);
  --tw-prose-headings: var(--mia-text-primary);
  --tw-prose-bold: var(--mia-text-primary);
  --tw-prose-links: var(--mia-accent);
  --tw-prose-code: var(--mia-accent-hover);
  font-family: 'Georgia', 'Cambria', 'Times New Roman', serif;
  font-size: 16px;
  font-weight: 450;
  line-height: 1.7;
  letter-spacing: -0.01em;
  color: var(--mia-text-ai);
}

.prose-mia p {
  font-weight: 450;
  color: var(--mia-text-ai);
}

.prose-mia strong,
.prose-mia h1,
.prose-mia h2,
.prose-mia h3,
.prose-mia h4 {
  font-weight: 600;
  color: var(--mia-text-primary);
  letter-spacing: -0.015em;
}

.prose-mia code {
  font-family: 'JetBrains Mono', 'Fira Code', monospace;
  font-size: 13px;
  background: hsl(35, 20%, 95%);
  padding: 2px 6px;
  border-radius: 6px;
  font-weight: 400;
}

.prose-mia pre {
  background: hsl(60, 5%, 12%);
  border: 1px solid hsl(60, 5%, 20%);
  border-radius: 12px;
  padding: 16px 20px;
  overflow-x: auto;
}

.prose-mia pre code {
  background: transparent;
  padding: 0;
  color: hsl(46, 40%, 90%);
}

.prose-mia blockquote {
  border-left: 3px solid var(--mia-accent);
  background: var(--mia-accent-subtle);
  padding: 12px 16px;
  border-radius: 0 8px 8px 0;
  font-style: italic;
}

.prose-mia table {
  border: 1px solid var(--mia-glass-border);
  border-radius: 8px;
  overflow: hidden;
}

.prose-mia th {
  background: var(--mia-accent-subtle);
  font-family: 'Poppins', sans-serif;
  font-weight: 600;
  font-size: 13px;
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

/* ── Animations ── */

@property --thinking-angle {
  syntax: '<angle>';
  initial-value: 0deg;
  inherits: false;
}

/* Rotating gradient border for thinking blocks */
@keyframes mia-thinking-rotate {
  to { --thinking-angle: 360deg; }
}

/* Text shimmer during thinking */
@keyframes mia-shimmer {
  0% { background-position: -200% 0; }
  100% { background-position: 200% 0; }
}

/* Cursor blink */
@keyframes mia-cursor-blink {
  0%, 100% { opacity: 1; }
  50% { opacity: 0; }
}

/* Subtle float for welcome avatar */
@keyframes mia-float {
  0%, 100% { transform: translateY(0); }
  50% { transform: translateY(-6px); }
}

/* Glow pulse for avatar */
@keyframes mia-glow-pulse {
  0%, 100% { opacity: 0.15; transform: scale(1); }
  50% { opacity: 0.3; transform: scale(1.05); }
}

.mia-thinking-block {
  position: relative;
  border-radius: 16px;
  padding: 1px; /* Border width via padding trick */
  background: conic-gradient(
    from var(--thinking-angle),
    var(--mia-thinking-from),
    var(--mia-thinking-to),
    transparent 40%,
    var(--mia-thinking-from)
  );
  animation: mia-thinking-rotate 3s linear infinite;
}

.mia-thinking-block.completed {
  background: var(--mia-thinking-border);
  animation: none;
}

.mia-thinking-block__inner {
  background: var(--mia-thinking-bg);
  border-radius: 15px; /* 16px - 1px border */
  padding: 12px 16px;
}

/* Shimmer no texto enquanto pensa */
.mia-thinking-text.streaming {
  background: linear-gradient(
    90deg,
    var(--mia-text-secondary) 0%,
    var(--mia-accent) 50%,
    var(--mia-text-secondary) 100%
  );
  background-size: 200% 100%;
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  animation: mia-shimmer 2s ease-in-out infinite;
}

@media (prefers-reduced-motion: reduce) {
  .mia-thinking-block { animation: none; }
  .mia-thinking-text.streaming { animation: none; -webkit-text-fill-color: var(--mia-text-secondary); }
  * { animation-duration: 0.01ms !important; transition-duration: 0.01ms !important; }
}

