import React, { useEffect, useLayoutEffect, useRef, useState } from "react";
import { useIsTablet } from "@/shared/hooks/use-mobile";
import { LogOut, Leaf, Sun, Moon } from "lucide-react";
import { categories } from "./menuItems";
import { useNavigate, useLocation } from "react-router-dom";
import { useAuth } from "@/shared/hooks/useAuth";
import { Button } from "@/shared/ui/button";
import { MiaGreetingCard } from "@/features/mia/ui/MiaGreetingCard";
// MiaMobileSheet removido — MIA agora é só pela página dedicada /mia
import { useSystemAnnouncements } from "@/features/announcements";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuLabel,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from "@/shared/ui/dropdown-menu";
import { Avatar, AvatarFallback } from "@/shared/ui/avatar";
import { StoreSelector } from "@/shared/ui/DashboardStoreSelector";
import { toast } from "sonner";
import { cn } from "@/shared/lib/utils";
import { useTheme } from "next-themes";
import { wideError } from "@/shared/lib/telemetry/wide-events";

type FeatureCardProps = {
  title: string;
  icon: React.ElementType;
  onClick: () => void;
};

function FeatureCard({ title, icon: Icon, onClick }: FeatureCardProps) {
  return (
    <button
      onClick={onClick}
      className="group flex flex-col items-center gap-3 p-3 transition-all duration-300 active:scale-95"
    >
      <div
        className={cn(
          'relative flex items-center justify-center h-[120px] w-[108px]',
          'rounded-t-[54px] rounded-b-[18px]',
          'bg-white dark:bg-[#1A1A1A]',
          'border-[2.5px] border-[#C5A065] dark:border-[#C5A065]/50',
          'shadow-[0_10px_28px_-8px_rgba(87,113,91,0.28),0_6px_12px_-3px_rgba(197,160,101,0.18)]',
          'group-hover:border-[#57715B] dark:group-hover:border-[#57715B] group-hover:shadow-[0_16px_32px_-8px_rgba(87,113,91,0.4)] transition-all duration-300',
        )}
      >
        <div className="absolute inset-[4px] rounded-t-[48px] rounded-b-[14px] border border-[#57715B]/10 dark:border-white/5 bg-[#57715B]/[0.02]" />
        <div className="absolute bottom-4 w-12 h-1.5 bg-[#C5A065] rounded-full opacity-40" />
        <Icon
          className="h-12 w-12 text-[#57715B] dark:text-[#8FA893] group-hover:scale-110 transition-transform duration-300 relative z-10 drop-shadow-sm"
          strokeWidth={1.5}
        />
      </div>

      <span className="text-sm font-bold tracking-wide text-[#2D362E] dark:text-[#E6DCCF] text-center leading-tight max-w-[120px] line-clamp-2 uppercase drop-shadow-sm group-hover:text-[#57715B] transition-colors">
        {title}
      </span>
    </button>
  );
}

export default function TabletHome() {
  const isTablet = useIsTablet();
  const navigate = useNavigate();
  const location = useLocation();
  const containerRef = useRef<HTMLDivElement | null>(null);
  const { theme, setTheme } = useTheme();
  const [serverVersion, setServerVersion] = useState<string | null>(null);

  useEffect(() => {
    fetch(`/version.json?t=${Date.now()}`)
      .then(res => res.json())
      .then(data => setServerVersion(data.version))
      .catch(err => wideError('dashboard.tablet_home.version_fetch_error', 'Falha ao buscar versão do servidor', { attributes: { 'error.message': err instanceof Error ? err.message : String(err), 'operation.name': 'fetchServerVersion' } }));
  }, []);

  const getInitialIndex = () => {
    const params = new URLSearchParams(location.search);
    const cat = (params.get('category') || '').toLowerCase();
    const idxByParam = categories.findIndex(
      (c) => c.name.toLowerCase() === cat,
    );
    if (idxByParam >= 0) return idxByParam;
    const estoqueIdx = categories.findIndex(
      (c) => c.name.toLowerCase() === 'estoque',
    );
    return estoqueIdx >= 0 ? estoqueIdx : 0;
  };

