// MIA Activity Glow — border glow ao redor da viewport quando MIA atua.
//
// Padrão Claude for Chrome: inset multi-layer box-shadow + pulse animation
// em opacity (GPU-friendly, sem repaint). Verde Momma --mia-accent quando
// ativa. Some suavemente (fade-out 500ms) quando idle.
//
// CPU: pulsa opacity (GPU-composited), NÃO box-shadow direto (repaint).

import { useMia, useMiaGlassBoxContext } from '@/shared/contexts/MiaContext';
import { cn } from '@/shared/lib/utils';

export function MiaActivityGlow() {
  const { miaModeEnabled, isExecuting, isPaused } = useMiaGlassBoxContext();
  const { isStreaming } = useMia();

  // Só ativo quando modo IA ligado E atuando E não pausado
  const active = miaModeEnabled && (isStreaming || isExecuting) && !isPaused;

  return (
    <div
      aria-hidden="true"
      className={cn(
        'fixed inset-0 z-[200] pointer-events-none',
        'transition-opacity duration-500 ease-out',
      )}
      style={{ opacity: active ? 1 : 0 }}
    >
      {/* Camada 1: border inset verde Momma — base do efeito */}
      <div
        className={cn(
          'absolute inset-0',
          active && 'animate-mia-border-pulse',
        )}
        style={{
          boxShadow: `
            inset 0 0 0 2px var(--mia-accent, #57715B),
            inset 0 0 14px 0 var(--mia-accent-glow, rgba(87,113,91,0.45)),
            inset 0 0 36px 0 var(--mia-accent-glow, rgba(87,113,91,0.30))
          `,
        }}
      />

      {/* Camada 2: glow outer mais difuso pra "aura" externa */}
      <div
        className={cn(
          'absolute inset-0',
          active && 'animate-mia-border-pulse-soft',
        )}
        style={{
          boxShadow: `inset 0 0 80px 0 var(--mia-accent-glow, rgba(87,113,91,0.20))`,
        }}
      />
    </div>
  );
}

