/**
 * MiaInlineChat — Chat da Mia renderizado inline como página do dashboard.
 *
 * Usa EXATAMENTE a mesma estrutura, componentes e dinâmicas da antiga rota
 * `/mia` (MiaPage.tsx): MiaChatHeader, MiaMessageList (com agentRounds,
 * thinkingBlocks, executionSteps, task plans, confirmations), MiaComposer,
 * MiaWelcome, MIA v2 toggle + reasoning mode.
 *
 * Diferença: traz a Mia para o design system Momma — fundo branco com faixa
 * de toldo, ícones decorativos animados, ambient glows e tipografia serif
 * sofisticada. A classe `mia-momma-surface` redefine as vars `--mia-bg*` para
 * serem transparentes, deixando os componentes internos herdarem o novo visual.
 */
import { useState, useCallback, useMemo } from 'react';
import { useMia } from '@/shared/contexts/MiaContext';
import {
  MiaChatHeader,
  MiaMessageList,
  MiaWelcome,
  MiaComposer,
} from './';
import { MiaAnnouncementsBanner } from '@/features/announcements';
import { Brain, Leaf, MessageCircle, Sparkles } from 'lucide-react';
import { cn } from '@/shared/lib/utils';
import '../styles/mia-chat.css';

export function MiaInlineChat() {
  const {
    messages,
    sendMessage,
    isStreaming,
    conversations,
    activeConversationId,
    startNewConversation,
    executionSteps,
    abortStream,
    streamingText,
    streamingStatus,
    thinkingBlocks,
    agentRounds,
    activeTaskPlan,
    approveTaskPlan,
    cancelTaskPlan,
    answerClarification,
    pendingConfirmation,
    confirmPendingActions,
    cancelPendingActions,
    rawMode,
    setRawMode,
    rawModeOptions,
    setRawModeOptions,
  } = useMia();

  const [input, setInput] = useState('');

  const activeConversation = useMemo(
    () => conversations.find((c) => c.id === activeConversationId),
    [conversations, activeConversationId],
  );

  const handleSend = useCallback(() => {
    const text = input.trim();
    if (!text || isStreaming) return;
    setInput('');
    sendMessage(text);
  }, [input, isStreaming, sendMessage]);

  const handleSuggestion = useCallback(
    (prompt: string) => {
      setInput('');
      sendMessage(prompt);
    },
    [sendMessage],
  );

  return (
    <div className="mia-momma-surface h-full w-full max-h-full bg-white dark:bg-[#0A0A0A] font-sans relative overflow-hidden transition-colors duration-300 flex flex-col">
      {/* Faixa de toldo Momma no topo */}
      <div
        className="absolute top-0 left-0 right-0 h-1.5 bg-[repeating-linear-gradient(90deg,#57715B,#57715B_20px,#ffffff_20px,#ffffff_40px)] opacity-80 z-50 shadow-sm pointer-events-none"
        aria-hidden="true"
      />

      {/* Ícones decorativos animados de fundo — GOLD DOURADO ALARANJADO
          (contraste quente com o verde veludo da Mia — harmonia triadic) */}
      <div
        className="absolute top-[6%] left-[3%] w-[280px] h-[280px] md:w-[380px] md:h-[380px] opacity-[0.05] dark:opacity-[0.07] pointer-events-none animate-pulse"
        style={{ animationDuration: '14s' }}
        aria-hidden="true"
      >
        <Sparkles className="w-full h-full text-[#D4A24A] -rotate-6" />
      </div>
      <div
        className="absolute bottom-[-6%] right-[3%] w-[320px] h-[320px] md:w-[460px] md:h-[460px] opacity-[0.05] dark:opacity-[0.07] pointer-events-none animate-pulse delay-1000"
        style={{ animationDuration: '16s' }}
        aria-hidden="true"
      >
        <Leaf className="w-full h-full text-[#C5A065] rotate-[20deg]" />
      </div>
      <div
        className="absolute top-[38%] right-[22%] w-[180px] h-[180px] md:w-[240px] md:h-[240px] opacity-[0.04] dark:opacity-[0.06] pointer-events-none animate-pulse delay-500"
        style={{ animationDuration: '18s' }}
        aria-hidden="true"
      >
        <MessageCircle className="w-full h-full text-[#D4A24A] rotate-[-12deg]" />
      </div>

      {/* Soft ambient glows — dourado alaranjado quente atrás do glass */}
      <div className="absolute top-[10%] left-[25%] w-[280px] h-[280px] md:w-[400px] md:h-[400px] bg-[#D4A24A]/10 rounded-full blur-[100px] pointer-events-none" />
      <div className="absolute bottom-[15%] right-[20%] w-[240px] h-[240px] md:w-[340px] md:h-[340px] bg-[#C5A065]/8 rounded-full blur-[100px] pointer-events-none" />

      {/* Main Chat Area — glassmorphism uniforme. Altura fixa via flex-1 do pai.
          Scroll interno somente na MessageList. */}
      <main className="relative z-10 flex-1 flex flex-col min-w-0 min-h-0 font-momma bg-white/60 dark:bg-black/20 backdrop-blur-xl saturate-150 overflow-hidden">
        {/* Header */}
        <MiaChatHeader
          conversationTitle={activeConversation?.title}
          onNewConversation={startNewConversation}
        />

        {/* Messages / Welcome View */}
        <MiaMessageList
          messages={messages}
          isStreaming={isStreaming}
          streamingText={streamingText}
          streamingStatus={streamingStatus}
          thinkingBlocks={thinkingBlocks}
          agentRounds={agentRounds}
          executionSteps={executionSteps}
          activeTaskPlan={activeTaskPlan}
          pendingConfirmation={pendingConfirmation}
          onConfirm={confirmPendingActions}
          onCancelConfirm={cancelPendingActions}
          onApproveTask={approveTaskPlan}
          onCancelTask={cancelTaskPlan}
          onClarificationAnswer={answerClarification}
          emptyState={
            <div className="flex flex-col items-center gap-6 w-full">
              <MiaWelcome onSelectSuggestion={handleSuggestion} />
              <div className="w-full max-w-3xl px-4">
                <MiaAnnouncementsBanner />
              </div>
            </div>
          }
        />

        {/* ── Composer fixo no bottom ── */}
        <div className="sticky bottom-0 left-0 right-0 z-10 px-3 sm:px-6 pb-4 pt-0">
          <div className="max-w-2xl mx-auto">
            {/* Mode controls — toggle raw mode (chat livre, sem harness) */}
            <div className="flex items-center gap-2 mb-2 px-2 overflow-x-auto scrollbar-hide">
              <button
                data-mia-skip
                onClick={() => setRawMode(!rawMode)}
                className={cn(
                  'inline-flex items-center gap-1.5 px-3 py-1 rounded-full text-[11px] font-medium transition-all duration-200 border whitespace-nowrap select-none',
                  !rawMode
                    ? 'bg-[--mia-accent] border-[--mia-accent] text-white'
                    : 'bg-white/70 dark:bg-white/5 border-[--mia-glass-border] text-[--mia-text-muted] hover:border-[--mia-accent]/30 hover:text-[--mia-text-secondary]',
                )}
                title={
                  rawMode
                    ? 'Ativar MIA (assistente Momma com dados internos)'
                    : 'Desativar MIA (chat livre)'
                }
              >
                <Sparkles className="h-3 w-3" />
                {rawMode ? 'MIA off' : 'MIA v2'}
              </button>

              {rawMode && (
                <button
                  data-mia-skip
                  onClick={() =>
                    setRawModeOptions({ reasoning: !rawModeOptions.reasoning })
                  }
                  className={cn(
                    'inline-flex items-center gap-1.5 px-3 py-1 rounded-full text-[11px] font-medium transition-all duration-200 border whitespace-nowrap select-none',
                    rawModeOptions.reasoning
                      ? 'bg-violet-500/10 border-violet-500/30 text-violet-600 dark:text-violet-400'
                      : 'bg-white/70 dark:bg-white/5 border-[--mia-glass-border] text-[--mia-text-muted] hover:border-violet-500/20 hover:text-[--mia-text-secondary]',
                  )}
                  title="Mostrar raciocínio da IA"
                >
                  <Brain className="h-3 w-3" />
                  Reasoning
                </button>
              )}

              {rawMode && (
                <span className="ml-auto text-[10px] text-[--mia-text-muted] whitespace-nowrap">
                  Chat livre
                </span>
              )}
            </div>

            <MiaComposer
              value={input}
              onChange={setInput}
              onSend={handleSend}
              onStop={abortStream}
              isStreaming={isStreaming}
              disabled={false}
            />
            <p className="mt-2 text-center text-[10px] text-[--mia-text-muted]/60">
              A MIA pode cometer erros — verifique informações importantes.
            </p>
          </div>
        </div>
      </main>
    </div>
  );
}

