1	import { renderHook, waitFor } from '@testing-library/react';
2	import { describe, it, expect, vi, beforeEach, afterEach } from 'vitest';
3	import {
4	  useIsMobile,
5	  useIsTablet,
6	  useDeviceMode,
7	  useHasCamera,
8	} from './use-mobile';
9	
10	type FakeMQL = {
11	  matches: boolean;
12	  media: string;
13	  onchange: null;
14	  addEventListener: ReturnType<typeof vi.fn>;
15	  removeEventListener: ReturnType<typeof vi.fn>;
16	  addListener: ReturnType<typeof vi.fn>;
17	  removeListener: ReturnType<typeof vi.fn>;
18	  dispatchEvent: ReturnType<typeof vi.fn>;
19	};
20	
21	function setViewport(width: number, height: number) {
22	  Object.defineProperty(window, 'innerWidth', {
23	    writable: true,
24	    configurable: true,
25	    value: width,
26	  });
27	  Object.defineProperty(window, 'innerHeight', {
28	    writable: true,
29	    configurable: true,
30	    value: height,
31	  });
32	}
33	
34	function installMatchMedia() {
35	  Object.defineProperty(window, 'matchMedia', {
36	    writable: true,
37	    configurable: true,
38	    value: vi.fn().mockImplementation(
39	      (query: string): FakeMQL => ({
40	        matches: false,
41	        media: query,
42	        onchange: null,
43	        addEventListener: vi.fn(),
44	        removeEventListener: vi.fn(),
45	        addListener: vi.fn(),
46	        removeListener: vi.fn(),
47	        dispatchEvent: vi.fn(),
48	      }),
49	    ),
50	  });
51	}
52	
53	describe('use-mobile hooks', () => {
54	  let originalWidth: number;
55	  let originalHeight: number;
56	
57	  beforeEach(() => {
58	    originalWidth = window.innerWidth;
59	    originalHeight = window.innerHeight;
60	    installMatchMedia();
61	  });
62	
63	  afterEach(() => {
64	    setViewport(originalWidth, originalHeight);
65	    vi.clearAllMocks();
66	  });
67	
68	  describe('useDeviceMode', () => {
69	    it('classifies viewport < 768 as mobile (any orientation)', () => {
70	      setViewport(500, 900);
71	      const { result } = renderHook(() => useDeviceMode());
72	      expect(result.current).toBe('mobile');
73	    });
74	
75	    it('classifies viewport >= 1280 as desktop', () => {
76	      setViewport(1440, 900);
77	      const { result } = renderHook(() => useDeviceMode());
78	      expect(result.current).toBe('desktop');
79	    });
80	
81	    it('classifies 768-1279 in landscape as tablet', () => {
82	      setViewport(1180, 810); // iPad landscape
83	      const { result } = renderHook(() => useDeviceMode());
84	      expect(result.current).toBe('tablet');
85	    });
86	
87	    it('classifies 768-1279 in portrait as mobile', () => {
88	      setViewport(810, 1180); // iPad portrait
89	      const { result } = renderHook(() => useDeviceMode());
90	      expect(result.current).toBe('mobile');
91	    });
92	
93	    it('boundary: 1280×800 landscape is desktop, not tablet', () => {
94	      setViewport(1280, 800);
95	      const { result } = renderHook(() => useDeviceMode());
96	      expect(result.current).toBe('desktop');
97	    });
98	  });
99	
100	  describe('useIsMobile', () => {
101	    it('returns true for tiny phones', () => {
102	      setViewport(375, 812);
103	      const { result } = renderHook(() => useIsMobile());
104	      expect(result.current).toBe(true);
105	    });
106	
107	    it('returns true for tablet portrait (essence-of-mobile spec)', () => {
108	      setViewport(810, 1180);
109	      const { result } = renderHook(() => useIsMobile());
110	      expect(result.current).toBe(true);
111	    });
112	
113	    it('returns false for tablet landscape', () => {
114	      setViewport(1180, 810);
115	      const { result } = renderHook(() => useIsMobile());
116	      expect(result.current).toBe(false);
