import { Button } from '@/shared/ui/button';
import { Popover, PopoverContent, PopoverTrigger } from '@/shared/ui/popover';
import { useMia } from '@/shared/contexts/MiaContext';
import { MiaHistoryPopoverContent } from './MiaHistoryPopover';

interface MiaChatHeaderProps {
  conversationTitle?: string;
  onNewConversation: () => void;
}

export function MiaChatHeader({
  conversationTitle,
  onNewConversation,
}: MiaChatHeaderProps) {
  const {
    conversations,
    activeConversationId,
    switchConversation,
    deleteConversation,
  } = useMia();
  const [popoverOpen, setPopoverOpen] = useState(false);
  const navigate = useNavigate();

  return (
    <header className="h-[60px] flex items-center justify-between px-3 lg:px-5 sticky top-0 z-20 shrink-0 border-b border-[--mia-glass-border]/40">
      <div className="flex items-center gap-2 overflow-hidden min-w-0">
        <Button
          variant="ghost"
          size="icon"
          onClick={() => navigate('/dashboard')}
          className="h-10 w-10 text-[--mia-text-secondary] hover:text-[--mia-text-primary] md:hidden shrink-0 -ml-1"
          title="Voltar ao painel"
        >
          <ChevronLeft className="h-6 w-6" />
        </Button>

        <h2 className="font-sans text-[15px] font-medium text-[--mia-text-primary] truncate">
          {conversationTitle || 'Nova Conversa'}
        </h2>
      </div>

      <div className="flex items-center gap-1.5 shrink-0">
        <Popover open={popoverOpen} onOpenChange={setPopoverOpen}>
          <PopoverTrigger asChild>
            <Button
              variant="ghost"
              size="sm"
              className="h-9 gap-1.5 rounded-xl text-[--mia-text-secondary] hover:text-[--mia-accent] hover:bg-[--mia-accent-subtle] px-2 md:px-3 transition-colors"
