// MIA Device Telemetry — captura info do device + timezone + locale.
//
// Helper único pra capturar contexto do client e injetar no pageContext
// que vai pro backend. Backend grava em mia_query_logs.device_info +
// user_timezone, e em mia_conversation_messages, etc.
//
// Capturado:
//   - user_agent (navegador + SO)
//   - viewport (width × height)
//   - device type heurística (mobile/tablet/desktop)
//   - resolução de tela
//   - touch support
//   - online/offline
//   - referrer
//   - timezone IANA (ex: America/Sao_Paulo)
//   - locale (ex: pt-BR)
//   - hora local em ISO
//   - connection type (4g/wifi se disponível)

export interface DeviceContext {
  user_agent: string;
  viewport_width: number;
  viewport_height: number;
  screen_width: number;
  screen_height: number;
  device_type: 'mobile' | 'tablet' | 'desktop';
  is_touch: boolean;
  is_online: boolean;
  language: string;
  languages: string[];
  timezone: string;
  locale: string;
  local_time_iso: string;
  referrer: string | null;
  connection_type: string | null;
  connection_effective_type: string | null;
  pathname: string;
  hash: string;
  search: string;
}

export function captureDeviceContext(): DeviceContext {
  const ua = typeof navigator !== 'undefined' ? navigator.userAgent : '';
  const isMobile = /Mobile|Android|iPhone|iPad|iPod/i.test(ua);
  const isTablet = /iPad|Tablet/i.test(ua) || (/Android/.test(ua) && !/Mobile/.test(ua));

  let connectionType: string | null = null;
  let connectionEffective: string | null = null;
  try {
    const conn = (navigator as any).connection;
    if (conn) {
      connectionType = conn.type ?? null;
      connectionEffective = conn.effectiveType ?? null;
    }
  } catch { /* noop */ }

  let timezone = 'UTC';
  try {
    timezone = Intl.DateTimeFormat().resolvedOptions().timeZone;
  } catch { /* noop */ }

  return {
    user_agent: ua,
    viewport_width: typeof window !== 'undefined' ? window.innerWidth : 0,
    viewport_height: typeof window !== 'undefined' ? window.innerHeight : 0,
    screen_width: typeof screen !== 'undefined' ? screen.width : 0,
    screen_height: typeof screen !== 'undefined' ? screen.height : 0,
    device_type: isTablet ? 'tablet' : (isMobile ? 'mobile' : 'desktop'),
    is_touch: typeof navigator !== 'undefined' && ('ontouchstart' in window || navigator.maxTouchPoints > 0),
    is_online: typeof navigator !== 'undefined' ? navigator.onLine : true,
    language: typeof navigator !== 'undefined' ? navigator.language : 'pt-BR',
    languages: typeof navigator !== 'undefined' ? Array.from(navigator.languages ?? []) : ['pt-BR'],
    timezone,
    locale: typeof navigator !== 'undefined' ? navigator.language : 'pt-BR',
    local_time_iso: new Date().toISOString(),
    referrer: typeof document !== 'undefined' ? document.referrer || null : null,
    connection_type: connectionType,
    connection_effective_type: connectionEffective,
    pathname: typeof window !== 'undefined' ? window.location.pathname : '',
    hash: typeof window !== 'undefined' ? window.location.hash : '',
    search: typeof window !== 'undefined' ? window.location.search : '',
  };
}

/**
 * Versão compacta pra injetar no payload backend sem inflar tokens.
 * Mantém só os campos essenciais pra debug.
 */
export function captureDeviceCompact() {
  const full = captureDeviceContext();
  return {
    device: full.device_type,
    viewport: `${full.viewport_width}x${full.viewport_height}`,
    timezone: full.timezone,
    locale: full.locale,
    online: full.is_online,
    connection: full.connection_effective_type,
    pathname: full.pathname,
  };
}
